class Solution {
public:
    int numberOfCombinations(string num) {
        const int MOD=1000000007; int n=num.size();
        if(num[0]=='0')return 0;
        vector<vector<int>>lcp(n+1,vector<int>(n+1));
        for(int i=n-1;i>=0;--i)for(int j=n-1;j>=0;--j)
            if(num[i]==num[j])lcp[i][j]=1+lcp[i+1][j+1];
        vector<vector<int>>pre(n+1,vector<int>(n+1));
        for(int end=1;end<=n;++end){
            for(int len=1;len<=end;++len){int start=end-len;long long ways=0;
                if(num[start]!='0'){
                    if(start==0)ways=1;
                    else{
                        ways=pre[start][min(len-1,start)];
                        if(start>=len){int a=start-len,b=start;
                            int same=lcp[a][b];
                            if(same>=len||num[a+same]<=num[b+same]){
                                int equal=(pre[start][len]-pre[start][len-1]+MOD)%MOD;
                                ways+=equal;
                            }
                        }
                    }
                }
                pre[end][len]=(pre[end][len-1]+ways)%MOD;
            }
        }
        return pre[n][n];
    }
};
